import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../components/DashboardLayout';
import {
  CreditCard, Loader2, CheckCircle, XCircle, Clock, ChevronDown, ChevronRight,
  FileText, ListChecks, Landmark,
} from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import { useViewContext } from '../contexts/ViewContext';
import { toast } from 'sonner';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || 'https://api.sigcr.com.br';
const API = `${BACKEND_URL}/api`;

const STATUS_EMPRESA_CFG = {
  pending: { label: 'Pendente', icon: Clock, className: 'bg-amber-500/10 text-amber-500 border-amber-500/20' },
  pendente_aprovacao: { label: 'Pendente', icon: Clock, className: 'bg-amber-500/10 text-amber-500 border-amber-500/20' },
  approved: { label: 'Aprovada', icon: CheckCircle, className: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' },
  aprovado_acesso_limitado: { label: 'Acesso Limitado', icon: CheckCircle, className: 'bg-sky-500/10 text-sky-400 border-sky-500/20' },
  ativo_contrato_assinado: { label: 'Contrato Ativo', icon: CheckCircle, className: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' },
  rejected: { label: 'Rejeitada', icon: XCircle, className: 'bg-red-500/10 text-red-500 border-red-500/20' },
  rejeitado: { label: 'Rejeitada', icon: XCircle, className: 'bg-red-500/10 text-red-500 border-red-500/20' },
};

const STATUS_SUBMISSAO_CFG = {
  rascunho: { label: 'Rascunho', className: 'bg-muted text-slate-600 border-input' },
  submetido: { label: 'Submetido', icon: FileText, className: 'bg-amber-500/10 text-amber-400 border-amber-500/20' },
  em_analise: { label: 'Em Análise', icon: Clock, className: 'bg-sky-500/10 text-sky-400 border-sky-500/20' },
  em_diligencia: { label: 'Em Diligência', icon: FileText, className: 'bg-primary-500/10 text-primary-400 border-primary-500/20' },
  homologado: { label: 'Homologado', icon: CheckCircle, className: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' },
};

const STATUS_ITEM_CFG = {
  pendente: { label: 'Pendente', icon: Clock, className: 'bg-muted text-slate-600 border-input' },
  enviado: { label: 'Enviado', icon: FileText, className: 'bg-amber-500/10 text-amber-400 border-amber-500/20' },
  conforme: { label: 'Conforme', icon: CheckCircle, className: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' },
  inconforme: { label: 'Inconforme', icon: XCircle, className: 'bg-red-500/10 text-red-500 border-red-500/20' },
};

const badge = (cfg, key, extra = '') => {
  const c = cfg[key] || cfg.pendente || Object.values(cfg)[0];
  return (
    <Badge className={`${c.className} font-mono uppercase text-[10px] px-2 py-0.5 ${extra}`}>
      {c.icon && <c.icon className="h-3 w-3 mr-1" />}{c.label}
    </Badge>
  );
};

// Espelha Registradoras.js ponto a ponto (mesmo layout, mesmo padrão de
// expandir/colapsar, mesmas configs de badge) — só troca a fonte de dados
// (/detran/financeiras em vez de /detran/registradoras) e adiciona o campo
// de registradora vinculada, que só existe pra financeira.
const Financeiras = () => {
  const { user, initialized } = useAuth();
  const { viewingAs } = useViewContext();
  const [ufs, setUfs] = useState([]);
  const [estadoSigla, setEstadoSigla] = useState(user?.detran_uf || '');
  const [financeiras, setFinanceiras] = useState([]);
  const [loading, setLoading] = useState(false);
  const [expandidas, setExpandidas] = useState({});

  // Quando sigcr_admin está simulando uma empresa (Registradora/Financeira)
  // via Trocar Visão, o seletor de UF (ação de admin) some mesmo com o JWT
  // real ainda sendo sigcr_admin — a simulação precisa refletir exatamente
  // o que a empresa vê.
  const ehAdmin = user?.perfil === 'sigcr_admin' && viewingAs?.tipo !== 'empresa';

  useEffect(() => {
    if (!ehAdmin) return;
    axios.get(`${API}/estados`, { withCredentials: true })
      .then((res) => setUfs(Array.isArray(res.data) ? res.data.filter((e) => e.configurado) : []))
      .catch(() => {});
  }, [ehAdmin]);

  const fetchFinanceiras = useCallback(async () => {
    if (!estadoSigla) return;
    setLoading(true);
    try {
      const res = await axios.get(`${API}/detran/financeiras`, {
        withCredentials: true, params: { estado_sigla: estadoSigla },
      });
      setFinanceiras(Array.isArray(res.data) ? res.data : []);
    } catch (error) {
      console.error('Erro ao carregar financeiras:', error);
      toast.error('Erro ao carregar financeiras');
    } finally {
      setLoading(false);
    }
  }, [estadoSigla]);

  useEffect(() => { if (initialized) fetchFinanceiras(); }, [initialized, fetchFinanceiras]);

  const toggleExpandida = (companyId) => setExpandidas((p) => ({ ...p, [companyId]: !p[companyId] }));

  return (
    <DashboardLayout>
      <div className="p-6 lg:p-8 space-y-8" data-testid="financeiras-page">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-foreground flex items-center gap-2">
              <CreditCard className="h-6 w-6 text-primary-400" />
              Financeiras
            </h1>
            <p className="text-slate-600 text-sm mt-1">
              Cadastro e status de credenciamento por portaria das financeiras que atuam nesta UF
            </p>
          </div>
          {ehAdmin && (
            <Select value={estadoSigla} onValueChange={setEstadoSigla}>
              <SelectTrigger className="w-48 bg-card border-input text-foreground">
                <SelectValue placeholder="Selecione a UF" />
              </SelectTrigger>
              <SelectContent className="bg-card border-input text-foreground">
                {ufs.map((e) => (
                  <SelectItem key={e.sigla} value={e.sigla}>{e.sigla} — {e.nome}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-16 text-slate-500 gap-3">
            <Loader2 className="h-5 w-5 animate-spin text-primary-400" />
            <span>Carregando...</span>
          </div>
        ) : !estadoSigla ? (
          <Card className="bg-card border-border">
            <CardContent className="p-12 text-center text-slate-600">Selecione uma UF para ver as financeiras.</CardContent>
          </Card>
        ) : financeiras.length === 0 ? (
          <Card className="bg-card border-border">
            <CardContent className="p-12 text-center">
              <CreditCard className="h-12 w-12 text-zinc-700 mx-auto mb-4" />
              <p className="text-slate-600">Nenhuma financeira atuando em {estadoSigla} ainda.</p>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-4">
            {financeiras.map((f) => {
              const expandida = !!expandidas[f.company_id];
              return (
                <Card key={f.company_id} className="bg-card border-border" data-testid={`financeira-card-${f.company_id}`}>
                  <CardContent className="p-5">
                    <button
                      onClick={() => toggleExpandida(f.company_id)}
                      className="w-full flex items-start justify-between gap-4 text-left"
                    >
                      <div className="min-w-0">
                        <div className="flex items-center gap-3 flex-wrap mb-1">
                          <p className="text-foreground font-semibold">{f.name}</p>
                          {badge(STATUS_EMPRESA_CFG, f.status)}
                        </div>
                        <p className="text-sm text-slate-600">{f.nome_fantasia}</p>
                        <p className="text-xs font-mono text-slate-500 mt-0.5">CNPJ: {f.cnpj}</p>
                        {f.registradora_nome_fantasia && (
                          <p className="text-xs text-slate-500 mt-1 flex items-center gap-1">
                            <Landmark className="h-3 w-3" /> Vinculada a {f.registradora_nome_fantasia}
                          </p>
                        )}
                      </div>
                      <div className="flex items-center gap-3 shrink-0">
                        <div className="text-right text-xs text-slate-500">
                          <p>{f.total_portarias_respondidas} portaria(s) respondida(s)</p>
                          <p>{f.total_homologadas} homologada(s)</p>
                        </div>
                        {expandida ? <ChevronDown className="h-4 w-4 text-slate-500" /> : <ChevronRight className="h-4 w-4 text-slate-500" />}
                      </div>
                    </button>

                    {expandida && (
                      <div className="mt-4 pt-4 border-t border-border space-y-4">
                        <div className="grid md:grid-cols-2 gap-4 text-sm">
                          <div>
                            <p className="text-slate-500 mb-1">Email Comercial:</p>
                            <p className="text-slate-700">{f.email_comercial}</p>
                          </div>
                          <div>
                            <p className="text-slate-500 mb-1">Gestor do Contrato:</p>
                            <p className="text-slate-700">{f.gestor_contrato}</p>
                          </div>
                          <div>
                            <p className="text-slate-500 mb-1">Endereço:</p>
                            <p className="text-slate-700">{f.endereco || '—'}</p>
                          </div>
                          <div>
                            <p className="text-slate-500 mb-1">WhatsApp:</p>
                            <p className="text-slate-700">{f.whatsapp || '—'}</p>
                          </div>
                        </div>
                        {f.detrans_atuacao?.length > 0 && (
                          <div>
                            <p className="text-xs text-slate-500 mb-2">DETRANs de Atuação:</p>
                            <div className="flex flex-wrap gap-2">
                              {f.detrans_atuacao.map((uf) => (
                                <Badge key={uf} className="bg-sky-500/10 text-sky-500 border-sky-500/20 text-xs">DETRAN-{uf}</Badge>
                              ))}
                            </div>
                          </div>
                        )}

                        <div>
                          <p className="text-xs text-slate-500 mb-2 flex items-center gap-1.5">
                            <ListChecks className="h-3.5 w-3.5" /> Credenciamento por Portaria
                          </p>
                          {f.submissoes.length === 0 ? (
                            <p className="text-sm text-slate-500">Nenhuma submissão ainda para portarias desta UF.</p>
                          ) : (
                            <div className="space-y-3">
                              {f.submissoes.map((s) => (
                                <div key={s.submissao_id} className="bg-background/50 border border-border rounded-lg p-3">
                                  <div className="flex items-center justify-between gap-3 flex-wrap mb-2">
                                    <p className="text-sm text-zinc-200">
                                      {s.portaria_numero ? `${s.portaria_numero} — ` : ''}{s.portaria_titulo || s.portaria_id}
                                    </p>
                                    {badge(STATUS_SUBMISSAO_CFG, s.status)}
                                  </div>
                                  <p className="text-xs text-slate-500 mb-2">
                                    {s.itens_conforme}/{s.total_itens} itens conformes
                                    {s.itens_inconforme > 0 && ` · ${s.itens_inconforme} inconforme(s)`}
                                    {s.itens_pendentes > 0 && ` · ${s.itens_pendentes} pendente(s)`}
                                  </p>
                                  <div className="flex flex-wrap gap-1.5">
                                    {s.itens.map((item) => (
                                      <span key={item.item_id} title={item.justificativa || item.nome}>
                                        {badge(STATUS_ITEM_CFG, item.status)}
                                      </span>
                                    ))}
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </div>
    </DashboardLayout>
  );
};

export default Financeiras;
